// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, LogFile} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    LogFile logFile;

    function setUp() public {
        c = new C();
        logFile = new LogFile();
    }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 1, 1 ether);

        c.SetLogFile(address(logFile));
        c.Initialized();

        vm.deal(actor, amount);
        vm.prank(actor);
        (bool ok,) = address(c).call{value: amount}(abi.encodeWithSignature("Deposit()"));

        assertTrue(ok, "Deposit with a configured LogFile must succeed");
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function test(uint256 v1, uint256 v2) public {
        require(v1 > 0 && v2 > 0 && v1 <= 1 ether && v2 <= 1 ether);
        require(address(this).balance >= v1 + v2);
        c.Deposit{value: v1}();
        c.Deposit{value: v2}();
        assert(c.balances(address(this)) == v1 + v2);
    }
    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest
{
    C c;

    constructor(C _c) { c = _c; }

    function runDeposit(uint256 amt, address logAddr) public
    {
        require(address(this).balance >= amt);
        c.SetLogFile(logAddr);
