contract InvMutTest
{
    C c;

    constructor(C _c) { c = _c; }

    function run(uint v) public
    {
        require(v > 0);
        // Before initialization this must succeed.
        c.SetMinSum(v);
        // Initialize.
        c.Initialized();
        // After initialization this must revert on P; capture via revert boolean.
        (bool ok2, ) = address(c).call(abi.encodeWithSelector(c.SetMinSum.selector, 2 * v));
        assert(c.MinSum() == v && !ok2);
    }
}

