contract InvMutTest
{
    C c;

    constructor(C _c) { c = _c; }

    fallback() external payable {}
    receive() external payable {}

    function test(uint amt) public
    {
        require(amt > 0);
        require(address(this).balance >= amt);
        // point the log at this contract; its fallback accepts AddMessage calls
        c.SetLogFile(address(this));
        c.Initialized();
        uint before = c.balances(address(this));
        (bool ok,) = address(c).call{value: amt}(abi.encodeWithSignature("Deposit()"));
        uint after_ = c.balances(address(this));
        assert(ok && after_ == before + amt);
    }
}

